#include "../charge_compiler/json.hpp"
#include "sparse_runs_v2.hpp"
#include <filesystem>
#include <iostream>
#include <sstream>
#include <thread>
#include <unordered_map>
#include <exception>
#include <time.h>
using I=long long;
static double now(){timespec t{};require(clock_gettime(CLOCK_BOOTTIME,&t)==0,"clock");return t.tv_sec+t.tv_nsec*1e-9;}
static std::string quoted(const std::string&s,size_t&p){auto a=s.find('"',p);require(a!=s.npos,"quoted EXT field");auto b=s.find('"',a+1);require(b!=s.npos,"quoted EXT end");p=b+1;return s.substr(a+1,b-a-1);}
struct Group {std::string name,id;sparse::Sum coupling,ground,exported,exported_abs;uint64_t nodes=0,grounds=0;};
int main(int argc,char**argv){try{
 require(argc==2,"usage CONFIG");auto cfg=Json::read(argv[1]);I threads=cfg.at("threads").integer();require(threads>0&&threads<=16,"thread bounds");double deadline=cfg.at("deadline_uptime").num();
 auto selected=Json::read(cfg.at("selected").str());std::vector<Group> groups;std::unordered_map<std::string,size_t> lookup;std::unordered_map<std::string,size_t> gids;
 for(auto&r:selected.at("selected_groups").arr()){Group g;g.name=r.at("original").str();g.id=std::to_string(r.at("group").integer());require(lookup.emplace(g.name,groups.size()).second&&gids.emplace(g.id,groups.size()).second,"unique selected groups");groups.push_back(g);}
 require(!groups.empty(),"nonempty groups");std::unordered_map<std::string,std::pair<size_t,bool>> native;std::ifstream input(cfg.at("native_nodes").str());require(bool(input),"native nodes open");std::string line;
 while(std::getline(input,line)){auto r=Json::parse(line);auto it=lookup.find(r.at("original_conductor").str());require(it!=lookup.end()&&groups[it->second].id==r.at("native_group_id").str(),"native node group identity");require(native.emplace(r.at("printed_name").str(),std::make_pair(it->second,false)).second,"unique native node name");}require(input.eof(),"native nodes complete");input.close();
 input.open(cfg.at("res_ext").str());require(bool(input),"res EXT open");uint64_t rnodes=0;
 while(std::getline(input,line)){if(rnodes%10000==0)require(now()<deadline,"res EXT audit deadline");if(!line.starts_with("rnode "))continue;size_t pos=0;auto name=quoted(line,pos);auto it=native.find(name);require(it!=native.end()&&!it->second.second,"exact unique final R node");it->second.second=true;std::istringstream tail(line.substr(pos));long double resistance,cap;require(bool(tail>>resistance>>cap)&&std::isfinite(cap),"R node cap");auto&g=groups[it->second.first];g.exported.add(cap);g.exported_abs.add(std::fabs(cap));g.nodes++;rnodes++;}require(input.eof()&&rnodes==native.size(),"all final R nodes covered");
 std::string ext=cfg.at("ext").str();uint64_t bytes=std::filesystem::file_size(ext);struct Part{std::vector<sparse::Sum> coupling,ground;std::vector<uint64_t> grounds;uint64_t caps=0;std::exception_ptr error;};std::vector<Part> parts(threads);std::vector<std::thread> jobs;
 for(I part=0;part<threads;part++)jobs.emplace_back([&,part]{auto&p=parts[part];try{p.coupling.resize(groups.size());p.ground.resize(groups.size());p.grounds.resize(groups.size());std::ifstream stream(ext,std::ios::binary);require(bool(stream),"EXT shard open");uint64_t begin=bytes*part/threads,end=bytes*(part+1)/threads;if(begin){stream.seekg(begin-1);char ch;stream.get(ch);if(ch!='\n'){std::string skip;std::getline(stream,skip);}}else stream.seekg(0);std::string text;uint64_t count=0;
 while(stream&&uint64_t(stream.tellg())<end&&std::getline(stream,text)){if(count++%10000==0)require(now()<deadline,"EXT audit deadline");size_t pos=0;if(text.starts_with("cap ")){p.caps++;auto a=quoted(text,pos),b=quoted(text,pos);auto x=lookup.find(a),y=lookup.find(b);if(x==lookup.end()&&y==lookup.end())continue;std::istringstream tail(text.substr(pos));long double cap;require(bool(tail>>cap)&&std::isfinite(cap),"EXT coupling token");if(x!=lookup.end())p.coupling[x->second].add(cap);if(y!=lookup.end())p.coupling[y->second].add(cap);}else if(text.starts_with("node ")||text.starts_with("substrate ")){auto name=quoted(text,pos);auto it=lookup.find(name);if(it==lookup.end())continue;std::istringstream tail(text.substr(pos));long double resistance,cap;require(bool(tail>>resistance>>cap)&&std::isfinite(cap),"EXT ground token");p.ground[it->second].add(cap);p.grounds[it->second]++;}}
 require(!stream.bad(),"complete EXT shard");}catch(...){p.error=std::current_exception();}});
 for(auto&t:jobs)t.join();uint64_t caps=0;for(auto&p:parts){if(p.error)std::rethrow_exception(p.error);caps+=p.caps;for(size_t i=0;i<groups.size();i++){groups[i].coupling.add(p.coupling[i].value());groups[i].ground.add(p.ground[i].value());groups[i].grounds+=p.grounds[i];}}
 std::ofstream rows(cfg.at("group_output").str());sparse::Sum coupling_sum,exported_sum,ground_sum,absolute_error;long double max_relative=0,max_absolute=0;uint64_t within_1e5=0;
 for(auto&g:groups){require(g.grounds==1&&g.nodes>0,"selected group full original/final node coverage");long double c=g.coupling.value(),r=g.exported.value(),ground=g.ground.value(),difference=r-c,denom=std::max(std::fabs(c),std::fabs(r));long double relative=denom==0?0:std::fabs(difference)/denom;coupling_sum.add(c);exported_sum.add(r);ground_sum.add(ground);absolute_error.add(std::fabs(difference));max_relative=std::max(max_relative,relative);max_absolute=std::max(max_absolute,std::fabs(difference));within_1e5+=relative<=1e-5L;
 Json row=Json::object();row["native_group_id"]=g.id;row["original_conductor"]=g.name;row["R_node_count"]=I(g.nodes);row["original_ground_C_raw"]=double(ground);row["incident_coupling_C_raw"]=double(c);row["exported_R_node_C_sum_raw"]=double(r);row["exported_R_node_C_absolute_sum_raw"]=double(g.exported_abs.value());row["exported_minus_incident_coupling_raw"]=double(difference);row["relative_difference_diagnostic"]=double(relative);rows<<row.dump()<<'\n';}rows.close();require(bool(rows),"group report close");
 Json report=Json::object();report["selected_groups"]=I(groups.size());report["final_R_nodes"]=I(rnodes);report["original_coupling_records_scanned"]=I(caps);report["selected_incident_coupling_C_sum_raw"]=double(coupling_sum.value());report["selected_original_ground_C_sum_raw"]=double(ground_sum.value());report["selected_exported_R_node_C_sum_raw"]=double(exported_sum.value());report["absolute_group_coupling_prediction_error_sum_raw"]=double(absolute_error.value());report["maximum_group_absolute_prediction_error_raw"]=double(max_absolute);report["maximum_group_relative_prediction_error_diagnostic"]=double(max_relative);report["groups_with_relative_prediction_error_le_1e5_diagnostic"]=I(within_1e5);std::ofstream out(cfg.at("report").str());out<<report.dump()<<'\n';require(bool(out),"summary close");return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
